<?php

declare(strict_types=1);

/* Phase 2F.2 test-schema-only persistence probe. No HTTP is performed. */
require dirname(__DIR__) . '/bootstrap/autoload.php';

use Araucaria\Livescore\Config\DatabaseUrl;
use Araucaria\Livescore\Database\DatabaseSafety;
use Araucaria\Livescore\Database\PdoConnectionFactory;
use Araucaria\Livescore\Ingestion\BandObservation;
use Araucaria\Livescore\Ingestion\NormalizedIngestionService;
use Araucaria\Livescore\Ingestion\NormalizedScoreObservation;
use Araucaria\Livescore\Ingestion\PdoIngestionRepository;
use Araucaria\Livescore\Ingestion\ReceiptResult;
use Araucaria\Livescore\Ingestion\RedactedReceipt;
use Araucaria\Livescore\Support\Sha256;
use Araucaria\Livescore\Support\StructuredLogger;
use PDO;
use RuntimeException;
use Throwable;

if (getenv('PHP_COLLECTOR_TEST_ONLY') !== '1') throw new RuntimeException('Refusing probe without PHP_COLLECTOR_TEST_ONLY=1.');
$url = getenv('DATABASE_URL'); if (!is_string($url) || $url === '') throw new RuntimeException('DATABASE_URL is required.');
$config = DatabaseUrl::parse($url); DatabaseSafety::requireUrlDatabase($config, DatabaseSafety::PERCONA57_TEST_DATABASE);
$pdo = PdoConnectionFactory::create($config); DatabaseSafety::requireTestDatabase($pdo, $config);
$tag = 'php-2f2-' . bin2hex(random_bytes(8));
$ids = ['source' => null, 'contest' => null, 'category' => null, 'otherContest' => null, 'otherCategory' => null, 'entries' => [], 'snapshots' => []];
$summary = array_fill_keys(['accepted', 'duplicate', 'timestamp_only', 'reset', 'aggregate_band_disagreement', 'category_rejection', 'partial', 'rejection_only', 'thrown_failure'], false);
$hashes = ['payload_sha256' => 0, 'normalized_fingerprint' => 0]; $canonical = ['canonical_score_events' => 0, 'current_scores' => 0, 'score_snapshot_flags' => 0]; $cleaned = false;

try {
    $now = '2026-09-14 00:00:00.000001'; setup($pdo, $ids, $tag, $now);
    $repository = new PdoIngestionRepository($pdo); $service = new NormalizedIngestionService($repository);
    $receipt = static fn (string $suffix): RedactedReceipt => new RedactedReceipt($ids['source'], $ids['contest'], null, null, $now, 'SYNTHETIC', 'GET', '/fixture?token=[REDACTED]', 200, 'application/json', ['safe' => 'fixture'], '{"safe":true}', Sha256::binary('fixture-' . $suffix), ['redacted_keys' => true], ['fixture' => $tag]);
    $observation = static fn (string $call, string $timestamp, string $score, string $qso, string $points, string $mult, array $bands): NormalizedScoreObservation => new NormalizedScoreObservation($ids['source'], $ids['contest'], $call, $call, $ids['category'], ['key' => 'FIXTURE'], $timestamp, $timestamp, 'CONFIRMED_UTC', $score, $qso, $points, $mult, ['aggregate_authoritative' => true], ['fixture' => $tag], $bands);

    // Explicit receipt state transitions plus the first accepted snapshot.
    $firstReceipt = $receipt('first'); $firstId = $repository->createReceipt($firstReceipt);
    assertRow($pdo, 'SELECT processing_status, processing_attempts, processing_started_at, processed_at FROM raw_messages WHERE id = ?', [$firstId], ['processing_status' => 'RECEIVED', 'processing_attempts' => 0, 'processing_started_at' => null, 'processed_at' => null], 'after create');
    $repository->claim($firstId, $now); $claimed = one($pdo, 'SELECT processing_status, processing_attempts, processing_started_at, processed_at FROM raw_messages WHERE id = ?', [$firstId]);
    ok($claimed['processing_status'] === 'PROCESSING' && (int) $claimed['processing_attempts'] === 1 && $claimed['processing_started_at'] !== null && $claimed['processed_at'] === null, 'after claim');
    $firstObs = $observation('LIFECYCLE', '2026-09-14 00:00:00.000001', '100', '100', '100', '1', [new BandObservation('40m', 'ALL', '100', '100', '1', null)]);
    $first = $repository->persistObservations($firstId, $now, [$firstObs]); ok($first[0]->outcome === 'ACCEPTED', 'first accepted'); $firstSnapshot = $first[0]->snapshotId; $firstEntry = $first[0]->entryId;
    $repository->finish($firstId, new ReceiptResult($firstId, 'PROCESSED', 1, 1, 0, 0));
    $finished = one($pdo, 'SELECT processing_status, processed_at, observation_count, accepted_count, duplicate_count, rejected_count, OCTET_LENGTH(payload_sha256) payload_length FROM raw_messages WHERE id = ?', [$firstId]);
    ok($finished['processing_status'] === 'PROCESSED' && $finished['processed_at'] !== null && (int) $finished['observation_count'] === 1 && (int) $finished['accepted_count'] === 1 && (int) $finished['duplicate_count'] === 0 && (int) $finished['rejected_count'] === 0, 'after finish'); $hashes['payload_sha256'] = (int) $finished['payload_length']; ok($hashes['payload_sha256'] === 32, 'payload hash length');
    $accepted = one($pdo, 'SELECT acceptance_status, score, qso_total, points_total, mult_total, OCTET_LENGTH(normalized_fingerprint) fingerprint_length FROM score_snapshots WHERE id = ?', [$firstSnapshot]);
    ok($accepted['acceptance_status'] === 'ACCEPTED' && (string) $accepted['score'] === '100' && (string) $accepted['qso_total'] === '100' && (string) $accepted['points_total'] === '100' && (string) $accepted['mult_total'] === '1' && countOf($pdo, 'SELECT COUNT(*) FROM band_snapshots WHERE snapshot_id = ?', [$firstSnapshot]) === 1, 'accepted snapshot aggregates and bands'); $hashes['normalized_fingerprint'] = (int) $accepted['fingerprint_length']; ok($hashes['normalized_fingerprint'] === 32, 'normalized hash length'); $summary['accepted'] = true;

    $snapshots = countOf($pdo, 'SELECT COUNT(*) FROM score_snapshots WHERE contest_id = ?', [$ids['contest']]); $bands = countOf($pdo, 'SELECT COUNT(*) FROM band_snapshots WHERE snapshot_id IN (SELECT id FROM score_snapshots WHERE contest_id = ?)', [$ids['contest']]);
    $duplicate = $service->ingest($receipt('duplicate'), [$firstObs]); ok($duplicate->duplicateCount === 1 && countOf($pdo, 'SELECT COUNT(*) FROM score_snapshots WHERE contest_id = ?', [$ids['contest']]) === $snapshots && countOf($pdo, 'SELECT COUNT(*) FROM band_snapshots WHERE snapshot_id IN (SELECT id FROM score_snapshots WHERE contest_id = ?)', [$ids['contest']]) === $bands, 'exact duplicate'); $summary['duplicate'] = true;
    $timestamp = $service->ingest($receipt('timestamp'), [$observation('LIFECYCLE', '2026-09-14 00:00:01.000001', '100', '100', '100', '1', [new BandObservation('40m', 'ALL', '100', '100', '1', null)])]); $timestampSnapshot = scalar($pdo, 'SELECT id FROM score_snapshots WHERE raw_message_id = ?', [$timestamp->rawMessageId]); ok($timestamp->acceptedCount === 1 && scalar($pdo, 'SELECT HEX(normalized_fingerprint) FROM score_snapshots WHERE id = ?', [$timestampSnapshot]) !== scalar($pdo, 'SELECT HEX(normalized_fingerprint) FROM score_snapshots WHERE id = ?', [$firstSnapshot]) && countOf($pdo, 'SELECT COUNT(*) FROM score_snapshots WHERE contest_id = ?', [$ids['contest']]) === $snapshots + 1, 'timestamp-only distinct'); $summary['timestamp_only'] = true;
    $reset = $service->ingest($receipt('reset'), [$observation('RESET', '2026-09-14 00:00:02.000001', '0', '0', '0', '0', [new BandObservation('40m', 'ALL', '0', '0', '0', null)])]); $resetSnapshot = scalar($pdo, 'SELECT id FROM score_snapshots WHERE raw_message_id = ?', [$reset->rawMessageId]); assertRow($pdo, 'SELECT score, qso_total, points_total, mult_total FROM score_snapshots WHERE id = ?', [$resetSnapshot], ['score' => 0, 'qso_total' => 0, 'points_total' => 0, 'mult_total' => 0], 'reset values'); ok($reset->acceptedCount === 1, 'reset accepted'); $summary['reset'] = true;
    $disagreement = $service->ingest($receipt('disagreement'), [$observation('DISAGREE', '2026-09-14 00:00:03.000001', '36594', '342', '50000', '107', [new BandObservation('80m', 'ALL', '10', '1000', '7', null), new BandObservation('40m', 'ALL', '20', '2000', '2', null)])]); $disagreementSnapshot = scalar($pdo, 'SELECT id FROM score_snapshots WHERE raw_message_id = ?', [$disagreement->rawMessageId]); ok((string) scalar($pdo, 'SELECT qso_total FROM score_snapshots WHERE id = ?', [$disagreementSnapshot]) === '342' && scalar($pdo, 'SELECT SUM(qso) FROM band_snapshots WHERE snapshot_id = ?', [$disagreementSnapshot]) === '30', 'aggregate band disagreement'); $summary['aggregate_band_disagreement'] = true;

    $entryBefore = countOf($pdo, 'SELECT COUNT(*) FROM entries WHERE contest_id = ? AND normalized_callsign = ?', [$ids['contest'], 'REJECTONLY']); $snapBefore = countOf($pdo, 'SELECT COUNT(*) FROM score_snapshots WHERE contest_id = ?', [$ids['contest']]); $bandBefore = countOf($pdo, 'SELECT COUNT(*) FROM band_snapshots WHERE snapshot_id IN (SELECT id FROM score_snapshots WHERE contest_id = ?)', [$ids['contest']]);
    $foreign = new NormalizedScoreObservation($ids['source'], $ids['contest'], 'REJECTONLY', 'REJECTONLY', $ids['otherCategory'], null, null, null, null, '0', '0', null, '0', null, null, []); $rejected = $service->ingest($receipt('category'), [$foreign]); ok($rejected->rejectedCount === 1 && countOf($pdo, 'SELECT COUNT(*) FROM entries WHERE contest_id = ? AND normalized_callsign = ?', [$ids['contest'], 'REJECTONLY']) === $entryBefore && countOf($pdo, 'SELECT COUNT(*) FROM score_snapshots WHERE contest_id = ?', [$ids['contest']]) === $snapBefore && countOf($pdo, 'SELECT COUNT(*) FROM band_snapshots WHERE snapshot_id IN (SELECT id FROM score_snapshots WHERE contest_id = ?)', [$ids['contest']]) === $bandBefore, 'category rejection non-mutation'); $summary['category_rejection'] = true;
    $partial = $service->ingest($receipt('partial'), [$observation('PARTIAL', '2026-09-14 00:00:04.000001', '1', '1', '1', '1', []), $foreign]); ok($partial->status === 'PARTIAL' && $partial->acceptedCount === 1 && $partial->rejectedCount === 1, 'mixed partial'); $summary['partial'] = true;
    $rejectionOnly = $service->ingest($receipt('rejection-only'), [], [['index' => 0, 'error' => 'Synthetic rejection.']]); assertRow($pdo, 'SELECT processing_status, accepted_count, duplicate_count, rejected_count FROM raw_messages WHERE id = ?', [$rejectionOnly->rawMessageId], ['processing_status' => 'FAILED', 'accepted_count' => 0, 'duplicate_count' => 0], 'rejection-only'); ok($rejectionOnly->rejectedCount > 0, 'rejection-only count'); $summary['rejection_only'] = true;
    $thrown = $service->ingestWithProcessor($receipt('thrown'), static function (): array { throw new RuntimeException('password=never-persist secret-token stack trace'); }); $throwRow = one($pdo, 'SELECT processing_status, processed_at, parse_error FROM raw_messages WHERE id = ?', [$thrown->rawMessageId]); ok($throwRow['processing_status'] === 'FAILED' && $throwRow['processed_at'] !== null && is_string($throwRow['parse_error']) && !str_contains($throwRow['parse_error'], 'never-persist') && !str_contains($throwRow['parse_error'], 'stack trace') && countOf($pdo, 'SELECT COUNT(*) FROM score_snapshots WHERE raw_message_id = ?', [$thrown->rawMessageId]) === 0, 'thrown failure durable and sanitized'); $summary['thrown_failure'] = true;

    $entryIds = values($pdo, 'SELECT id FROM entries WHERE contest_id = ?', [$ids['contest']]); $snapshotIds = values($pdo, 'SELECT id FROM score_snapshots WHERE contest_id = ?', [$ids['contest']]); $ids['entries'] = $entryIds; $ids['snapshots'] = $snapshotIds;
    $canonical['canonical_score_events'] = countOf($pdo, 'SELECT COUNT(*) FROM canonical_score_events WHERE score_snapshot_id IN (' . marks($snapshotIds) . ')', $snapshotIds); $canonical['score_snapshot_flags'] = countOf($pdo, 'SELECT COUNT(*) FROM score_snapshot_flags WHERE snapshot_id IN (' . marks($snapshotIds) . ')', $snapshotIds); $canonical['current_scores'] = countOf($pdo, 'SELECT COUNT(*) FROM current_scores WHERE entry_id IN (' . marks($entryIds) . ')', $entryIds); ok($canonical['canonical_score_events'] === 0 && $canonical['current_scores'] === 0 && $canonical['score_snapshot_flags'] === 0, 'canonical side effects');
    cleanup($pdo, $ids); $cleaned = true; ok(remaining($pdo, $ids) === 0, 'post-cleanup zero fixture rows');
} catch (Throwable $error) {
    if (!$cleaned) { try { cleanup($pdo, $ids); ok(remaining($pdo, $ids) === 0, 'failure cleanup'); } catch (Throwable) { throw new RuntimeException('Probe failed and fixture cleanup failed.'); } }
    throw $error;
}
StructuredLogger::event('PHP_INGESTION_PROBE_PASS', ['fixture' => $tag, 'schema' => DatabaseSafety::PERCONA57_TEST_DATABASE, 'scenarios' => $summary, 'hash_lengths' => $hashes, 'canonical_side_effects' => $canonical, 'cleanup_remaining_fixture_rows' => 0]);

function setup(PDO $pdo, array &$ids, string $tag, string $now): void { $pdo->prepare("INSERT INTO sources (code,kind,precedence_rank,display_name,enabled,created_at,updated_at) VALUES (?,'FIXTURE',250,?,1,?,?)")->execute([$tag,$tag,$now,$now]); $ids['source']=(string)$pdo->lastInsertId(); foreach ([['contest',$tag],['otherContest',$tag.'-other']] as [$key,$name]) { $pdo->prepare("INSERT INTO contests (name,normalized_name,slug,status,time_zone,created_at,updated_at) VALUES (?,?,?,'SCHEDULED','UTC',?,?)")->execute([$name,$name,$name,$now,$now]); $ids[$key]=(string)$pdo->lastInsertId(); } foreach ([['contest','category'],['otherContest','otherCategory']] as [$contest,$key]) { $pdo->prepare("INSERT INTO contest_categories (contest_id,category_key,display_name,active,created_at,updated_at) VALUES (?,'FIXTURE',?,1,?,?)")->execute([$ids[$contest],$tag,$now,$now]); $ids[$key]=(string)$pdo->lastInsertId(); } }
function cleanup(PDO $pdo, array $ids): void { $pdo->prepare('DELETE FROM current_scores WHERE entry_id IN (SELECT id FROM entries WHERE contest_id=?)')->execute([$ids['contest']]); foreach (['score_snapshot_flags'=>'snapshot_id','canonical_score_events'=>'score_snapshot_id','band_snapshots'=>'snapshot_id'] as $table=>$column) $pdo->prepare("DELETE FROM {$table} WHERE {$column} IN (SELECT id FROM score_snapshots WHERE contest_id=?)")->execute([$ids['contest']]); $pdo->prepare('DELETE FROM score_snapshots WHERE contest_id=?')->execute([$ids['contest']]); $pdo->prepare('DELETE FROM raw_messages WHERE source_id=?')->execute([$ids['source']]); $pdo->prepare('DELETE FROM entries WHERE contest_id=?')->execute([$ids['contest']]); foreach ([$ids['contest'],$ids['otherContest']] as $contest) { $pdo->prepare('DELETE FROM contest_categories WHERE contest_id=?')->execute([$contest]); $pdo->prepare('DELETE FROM contests WHERE id=?')->execute([$contest]); } $pdo->prepare('DELETE FROM sources WHERE id=?')->execute([$ids['source']]); }
function remaining(PDO $pdo,array $ids):int { $total=countOf($pdo,'SELECT COUNT(*) FROM sources WHERE id=?',[$ids['source']])+countOf($pdo,'SELECT COUNT(*) FROM contests WHERE id IN (?,?)',[$ids['contest'],$ids['otherContest']])+countOf($pdo,'SELECT COUNT(*) FROM contest_categories WHERE id IN (?,?)',[$ids['category'],$ids['otherCategory']])+countOf($pdo,'SELECT COUNT(*) FROM entries WHERE contest_id=?',[$ids['contest']])+countOf($pdo,'SELECT COUNT(*) FROM raw_messages WHERE source_id=?',[$ids['source']])+countOf($pdo,'SELECT COUNT(*) FROM score_snapshots WHERE contest_id=?',[$ids['contest']])+countOf($pdo,'SELECT COUNT(*) FROM collector_source_contests WHERE source_id=? OR contest_id=?',[$ids['source'],$ids['contest']])+countOf($pdo,'SELECT COUNT(*) FROM collector_runs WHERE source_id=?',[$ids['source']]); if($ids['snapshots']!==[])$total+=countOf($pdo,'SELECT COUNT(*) FROM band_snapshots WHERE snapshot_id IN ('.marks($ids['snapshots']).')',$ids['snapshots'])+countOf($pdo,'SELECT COUNT(*) FROM score_snapshot_flags WHERE snapshot_id IN ('.marks($ids['snapshots']).')',$ids['snapshots'])+countOf($pdo,'SELECT COUNT(*) FROM canonical_score_events WHERE score_snapshot_id IN ('.marks($ids['snapshots']).')',$ids['snapshots']); if($ids['entries']!==[])$total+=countOf($pdo,'SELECT COUNT(*) FROM current_scores WHERE entry_id IN ('.marks($ids['entries']).')',$ids['entries']); return $total; }
function one(PDO $pdo,string $sql,array $params):array { $s=$pdo->prepare($sql);$s->execute($params);$v=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($v))throw new RuntimeException('Probe expected row.');return $v; } function scalar(PDO $pdo,string $sql,array $params):string { $s=$pdo->prepare($sql);$s->execute($params);$v=$s->fetchColumn();if(!is_scalar($v))throw new RuntimeException('Probe expected scalar.');return(string)$v; } function countOf(PDO $pdo,string $sql,array $params):int{return(int)scalar($pdo,$sql,$params);} function values(PDO $pdo,string $sql,array $params):array{$s=$pdo->prepare($sql);$s->execute($params);return array_map('strval',$s->fetchAll(PDO::FETCH_COLUMN));} function marks(array $ids):string{if($ids===[])throw new RuntimeException('Probe expected IDs.');return implode(',',array_fill(0,count($ids),'?'));} function assertRow(PDO $pdo,string $sql,array $params,array $expected,string $name):void{$actual=one($pdo,$sql,$params);foreach($expected as $key=>$value)ok($actual[$key]===$value,$name.': '.$key);} function ok(bool $condition,string $name):void{if(!$condition)throw new RuntimeException("Probe assertion failed: {$name}");}
